package com.lamggm.rospocket;
import android.content.*;import android.view.*;import android.widget.*;import java.io.*;import java.nio.file.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31)
public class DashboardBoardTest {
 Context c;File root;
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();root=c.getFilesDir();new File(root,"dashboard-layout-v1.json").delete();new File(root,"dashboard-layout-v1.json.new").delete();new File(root,"dashboard-layout-v1.json.bak").delete();}

 @Test public void actualResizeHandleChangesDraftAndStaleGestureCannotChangeANewEditor(){DashboardBoard b=board();b.edit();b.measure(View.MeasureSpec.makeMeasureSpec(1200,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));b.layout(0,0,1200,b.getMeasuredHeight());View handle=b.findViewWithTag("layout-resize:sensors");send(handle,0,20,20);send(handle,2,330,200);send(handle,1,330,200);assertEquals(3,b.layout().get("sensors").width);assertEquals(3,b.layout().get("sensors").height);send(handle,0,20,20);b.cancel();b.edit();send(handle,2,800,500);send(handle,1,800,500);assertEquals(2,b.layout().get("sensors").width);assertEquals(2,b.layout().get("sensors").height);}
 static void send(View view,int action,float x,float y){android.view.MotionEvent e=android.view.MotionEvent.obtain(0,10,action,x,y,0);try{view.dispatchTouchEvent(e);}finally{e.recycle();}}
 @Test public void failedSaveKeepsDraftAndCommittedFileForRetry()throws Exception{DashboardBoard b=board();b.edit();assertTrue(b.save());String old=new DashboardStore(root).load().encode();b.edit();b.resize("plot",4,4);assertTrue(new File(root,"dashboard-layout-v1.json.new").mkdir());assertFalse(b.save());assertTrue(b.editing());assertEquals(4,b.layout().get("plot").height);assertEquals(old,new DashboardStore(root).load().encode());}

 @Test public void postCommitObserverFailureNeverClaimsOldLayoutWasPreserved()throws Exception{DashboardBoard b=board();b.edit();assertTrue(b.save());DashboardStore fault=new DashboardStore(root){@Override void verify(DashboardLayout expected)throws IOException{assertEquals("Fault occurs after real file commit",expected.encode(),new DashboardStore(root).load().encode());throw new IOException("injected post-commit observer failure");}};java.lang.reflect.Field field=DashboardBoard.class.getDeclaredField("store");field.setAccessible(true);field.set(b,fault);b.edit();b.resize("sensors",4,3);assertFalse(b.save());assertTrue(b.editing());assertTrue("UI must explicitly admit unknown persistence",ConnectionActivityTest.textOf(b).contains("incerto"));b.cancel();View warning=b.findViewWithTag("dashboard-persistence-status");assertNotNull(warning);assertEquals("Cancel discards only draft, must not hide unknown durable state",View.VISIBLE,warning.getVisibility());assertEquals(4,new DashboardStore(root).load().get("sensors").width);}
 @Test public void postCommitFailureHasDistinctUnknownOutcome()throws Exception{DashboardStore fault=new DashboardStore(root){@Override void verify(DashboardLayout layout)throws IOException{throw new IOException("injected readback failure");}};IOException failure=assertThrows(IOException.class,()->fault.save(DashboardLayout.defaults().resize("plot",4,3)));assertTrue("Committed write is not a pre-commit failure",failure.getMessage().contains("incerto"));assertEquals(4,new DashboardStore(root).load().get("plot").width);}
 private DashboardBoard board(){DashboardBoard b=new DashboardBoard(c);for(String id:DashboardLayout.IDS)b.addCard(id,id,new TextView(c),null);return b;}
 @Test public void editingIsADraftSavePersistsCancelAndResetDoNotWrite()throws Exception{DashboardBoard b=board();assertNotNull(b.findViewWithTag("dashboard-edit"));assertFalse(b.editing());b.edit();assertTrue(b.editing());b.resize("sensors",4,3);b.moveBefore("sensors","watch0");assertEquals("sensors",b.layout().items.get(0).id);assertEquals(2,new DashboardStore(root).load().get("sensors").width);assertTrue(b.save());assertFalse(b.editing());assertEquals(b.layout().encode(),board().layout().encode());b.edit();b.resize("sensors",2,2);b.cancel();assertEquals(4,b.layout().get("sensors").width);assertEquals(b.layout().encode(),new DashboardStore(root).load().encode());b.edit();b.findViewWithTag("dashboard-reset").performClick();assertEquals(DashboardLayout.defaults().encode(),b.layout().encode());assertEquals(4,new DashboardStore(root).load().get("sensors").width);b.cancel();assertEquals(4,b.layout().get("sensors").width);}
 @Test public void resizeAndReorderNeverReparentCardsOrAllowOverlappingSlots(){DashboardBoard b=board();b.measure(View.MeasureSpec.makeMeasureSpec(1200,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));b.layout(0,0,1200,b.getMeasuredHeight());View sensor=b.findViewWithTag("dashboard-card:sensors"),robot=b.findViewWithTag("dashboard-card:robot");assertNotNull(sensor);assertNotNull(robot);android.view.ViewParent parent=robot.getParent();b.edit();b.resize("robot",2,2);b.moveBefore("sensors","robot");b.measure(View.MeasureSpec.makeMeasureSpec(1200,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));b.layout(0,0,1200,b.getMeasuredHeight());assertSame(parent,robot.getParent());assertSame(parent,sensor.getParent());assertEquals(sensor.getTop(),robot.getTop());assertTrue(sensor.getRight()<=robot.getLeft());assertTrue(sensor.getHeight()>200);}
 @Test public void badFileFallsBackWithoutDeletingItAndAtomicFailureKeepsCommittedLayout()throws Exception{DashboardStore s=new DashboardStore(root);File base=new File(root,"dashboard-layout-v1.json");Files.write(base.toPath(),"bad layout".getBytes());assertEquals(DashboardLayout.defaults().encode(),s.load().encode());assertEquals("bad layout",new String(Files.readAllBytes(base.toPath())));DashboardLayout first=DashboardLayout.defaults().resize("robot",2,2);s.save(first);assertEquals(first.encode(),s.load().encode());assertTrue(new File(root,"dashboard-layout-v1.json.new").mkdir());assertThrows(IOException.class,()->s.save(first.resize("plot",4,3)));assertEquals(first.encode(),s.load().encode());}
}
